export const defaults={language:'it',theme:'dark',animation:'normal',coordinates:true,legal:true,sound:false,quality:'deep',coachDetail:'compact',coachTone:'warm',coachHints:true,coachFrequency:'all',coachPreset:'milo',board:'amethyst',avatarColor:'sage',avatarShape:'round',avatarEyes:'friendly',avatarAccessory:'none',coachName:'Milo'};
const choices={language:['it','en','es','fr','de'],theme:['system','light','dark'],animation:['normal','slow','off'],quality:['quick','standard','deep'],coachDetail:['guided','compact'],coachTone:['warm','direct','quiet'],coachFrequency:['all','errors'],coachPreset:['milo','astra','nox','custom'],board:['amethyst','lavender','green','walnut','slate'],avatarColor:['sage','sky','plum','sun'],avatarShape:['round','square','cat'],avatarEyes:['friendly','focused','happy'],avatarAccessory:['none','glasses','crown','headphones']};
export function sanitizeSettings(value){const out={...defaults};if(!value||typeof value!=='object')return out;for(const key of Object.keys(defaults)){if(choices[key]?.includes(value[key]))out[key]=value[key];else if(typeof defaults[key]==='boolean'&&typeof value[key]==='boolean')out[key]=value[key]}if(typeof value.coachName==='string')out.coachName=value.coachName.trim().slice(0,18)||defaults.coachName;out.quality="deep";return out}
let settings=defaults;try{settings=sanitizeSettings(JSON.parse(localStorage.getItem('plystreak-settings')))}catch{}
export const getSettings=()=>({...settings});
export function saveSettings(patch){settings=sanitizeSettings({...settings,...patch});let saved=true;try{localStorage.setItem('plystreak-settings',JSON.stringify(settings))}catch{saved=false}applySettings();window.dispatchEvent(new CustomEvent('ply-settings',{detail:settings}));return saved}
export function applySettings(){if(typeof document==='undefined')return;const root=document.documentElement;root.dataset.theme=settings.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):settings.theme;root.dataset.coordinates=String(settings.coordinates);root.dataset.legal=String(settings.legal);root.dataset.board=settings.board;root.dataset.motion=settings.animation;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',root.dataset.theme==='dark'?'#100d16':'#f6f3fb')}
export const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function avatarSVG(s=settings){s=sanitizeSettings(s);const colors={sage:['#b4d29a','#456147'],sky:['#9acfe3','#315d7d'],plum:['#d5b5e8','#72528b'],sun:['#f1cd84','#997244']};const [a,b]=colors[s.avatarColor];const face=s.avatarShape==='square'?'<rect x="29" y="35" width="102" height="97" rx="24"/>':s.avatarShape==='cat'?'<path d="M30 74 28 25 61 45Q80 35 99 45L132 25 130 74Q148 133 80 137 12 133 30 74Z"/>':'<rect x="27" y="35" width="106" height="100" rx="47"/>';
const eyes=s.avatarEyes==='happy'?'<path d="M48 84q8-12 16 0m32 0q8-12 16 0" fill="none" stroke="'+b+'" stroke-width="6" stroke-linecap="round"/>':s.avatarEyes==='focused'?'<path d="m48 73 18 6m28 0 18-6" stroke="'+b+'" stroke-width="5"/><circle cx="57" cy="86" r="5"/><circle cx="103" cy="86" r="5"/>':'<ellipse cx="57" cy="83" rx="6" ry="9"/><ellipse cx="103" cy="83" rx="6" ry="9"/>';
const accessory=s.avatarAccessory==='glasses'?'<g fill="none" stroke="'+b+'" stroke-width="4"><circle cx="57" cy="84" r="16"/><circle cx="103" cy="84" r="16"/><path d="M73 84h14"/></g>':s.avatarAccessory==='crown'?'<path d="m51 43-6-24 20 12L80 11l15 20 20-12-6 24Z" fill="#f5c969" stroke="#a57a34" stroke-width="3"/>':s.avatarAccessory==='headphones'?'<path d="M25 91V77a55 55 0 0 1 110 0v14" fill="none" stroke="'+b+'" stroke-width="9"/><rect x="16" y="74" width="16" height="32" rx="8" fill="'+b+'"/><rect x="128" y="74" width="16" height="32" rx="8" fill="'+b+'"/>':'';
return `<svg viewBox="0 0 160 160" role="img" aria-label="Avatar illustrato del coach" xmlns="http://www.w3.org/2000/svg"><circle cx="80" cy="80" r="77" fill="${a}" opacity=".25"/><ellipse cx="80" cy="141" rx="37" ry="8" fill="${b}" opacity=".14"/><g fill="${a}" stroke="${b}" stroke-width="3">${face}</g><g fill="${b}">${eyes}</g><path d="M66 108q14 12 28 0" fill="none" stroke="${b}" stroke-width="4" stroke-linecap="round"/>${accessory}</svg>`}
export function playSound(){if(!settings.sound)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)();const oscillator=ctx.createOscillator(),gain=ctx.createGain();oscillator.connect(gain);gain.connect(ctx.destination);oscillator.frequency.setValueAtTime(540,ctx.currentTime);oscillator.frequency.exponentialRampToValueAtTime(320,ctx.currentTime+.08);gain.gain.setValueAtTime(.08,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);oscillator.start();oscillator.stop(ctx.currentTime+.13);oscillator.onended=()=>ctx.close()}catch{}}
if(typeof window!=='undefined'){applySettings();matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applySettings);window.addEventListener('storage',e=>{if(e.key==='plystreak-settings'){try{settings=sanitizeSettings(JSON.parse(e.newValue));applySettings();window.dispatchEvent(new CustomEvent('ply-settings',{detail:settings}))}catch{}}})}
